export const el3Tasks={"sources": [{"id": "compare", "title": "Compare and explain", "kind": "sources", "type": "compare", "cases": [["0", "An alternating potential difference…", ["Repeatedly reverses polarity", "Must always stay positive", "Is used up by a resistor"], 0, "Its sign changes repeatedly."], ["1", "A battery normally supplies…", ["UK mains ac", "Direct potential difference", "No potential difference"], 1, "Its polarity stays the same."], ["2", "UK domestic mains frequency is…", ["230 Hz", "100 Hz", "50 Hz"], 2, "Frequency counts full cycles per second."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "sources-data", "type": "numeric", "prompt": "An ac supply completes 120 cycles in 2 seconds. Calculate frequency.", "answer": 60, "unit": "Hz", "reasonChoices": ["120 ÷ 2", "120 × 2", "2 ÷ 120"], "reason": 0, "why": "Use the stated quantities, relationship and units."}, {"id": "model", "title": "Predict and compare every setting", "kind": "sources-model", "type": "experiment", "experiment": "sources", "why": "Check the selected values and predict the displayed quantity."}], "mains": [{"id": "compare", "title": "Compare and explain", "kind": "mains", "type": "compare", "cases": [["0", "The live insulation colour is…", ["Brown", "Blue", "Green/yellow stripes"], 0, "Identify the wire by its role and insulation."], ["1", "The neutral wire normally…", ["Carries current only in a case fault", "Completes the operating circuit", "Makes every live wire safe to touch"], 1, "Neutral is the operating return."], ["2", "Protective earth insulation is…", ["Plain brown", "Blue", "Green/yellow stripes"], 2, "Its labelled striped identity distinguishes it from neutral."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "mains-data", "type": "numeric", "prompt": "Use nominal live potential 230 V and earth potential 0 V. Calculate their potential difference.", "answer": 230, "unit": "V", "reasonChoices": ["230 − 0", "230 × 0", "0 ÷ 230"], "reason": 0, "why": "Use the stated quantities, relationship and units."}, {"id": "model", "title": "Predict and compare every setting", "kind": "mains-model", "type": "experiment", "experiment": "mains", "why": "Check the selected values and predict the displayed quantity."}], "power": [{"id": "compare", "title": "Compare and explain", "kind": "power", "type": "compare", "cases": [["0", "A watt is…", ["One joule per second", "One joule stored permanently", "One coulomb per volt"], 0, "Power measures a rate."], ["1", "Power from potential difference and current is…", ["P = V/I", "P = VI", "P = I/V"], 1, "Multiply volts by amperes."], ["2", "A 12 V device drawing 2 A has input power…", ["6 W", "0.167 W", "24 W"], 2, "12 × 2 = 24."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "power-data", "type": "numeric", "prompt": "A fresh resistor carries 3 A and has resistance 8 Ω. Calculate power.", "answer": 72, "unit": "W", "reasonChoices": ["3² × 8", "3 × 8", "8 ÷ 3"], "reason": 0, "why": "Use the stated quantities, relationship and units."}, {"id": "model", "title": "Predict and compare every setting", "kind": "power-model", "type": "experiment", "experiment": "power", "why": "Check the selected values and predict the displayed quantity."}], "appliances": [{"id": "compare", "title": "Compare and explain", "kind": "appliances", "type": "compare", "cases": [["0", "A battery fan transfers energy from the battery’s…", ["Chemical store, electrically to motion and heating", "Supply of used-up electrons", "Kinetic store only"], 0, "Name a source store and transfer pathway."], ["1", "Electrical energy from constant power and duration is…", ["E = P/t", "E = Pt", "E = t/P"], 1, "Power is energy per second."], ["2", "100 W for 30 s transfers…", ["3.33 J", "130 J", "3000 J"], 2, "100 × 30 = 3000."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "appliances-data", "type": "numeric", "prompt": "A fresh motor transfers 360 J when 30 C passes. Calculate its potential difference.", "answer": 12, "unit": "V", "reasonChoices": ["360 ÷ 30", "360 × 30", "30 ÷ 360"], "reason": 0, "why": "Use the stated quantities, relationship and units."}, {"id": "model", "title": "Predict and compare every setting", "kind": "appliances-model", "type": "experiment", "experiment": "appliances", "why": "Check the selected values and predict the displayed quantity."}], "grid": [{"id": "compare", "title": "Compare and explain", "kind": "grid", "type": "compare", "cases": [["0", "The National Grid links stations and consumers with…", ["Cables and transformers", "Only batteries in series", "Only neutral wires"], 0, "It is a transmission network."], ["1", "Before transmission a step-up transformer…", ["Creates extra energy", "Increases potential difference", "Necessarily increases current at fixed power"], 1, "Higher voltage allows lower current for a given power."], ["2", "Cable heating at fixed resistance depends on…", ["I/R only", "Voltage colour on a map", "I²R"], 2, "Lower current reduces heating strongly."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "grid-data", "type": "numeric", "prompt": "A fresh line sends 2000 W at 400 V. Calculate current.", "answer": 5, "unit": "A", "reasonChoices": ["2000 ÷ 400", "2000 × 400", "400 ÷ 2000"], "reason": 0, "why": "Use the stated quantities, relationship and units."}, {"id": "model", "title": "Predict and compare every setting", "kind": "grid-model", "type": "experiment", "experiment": "grid", "why": "Check the selected values and predict the displayed quantity."}, {"id": "transformer", "title": "Higher: conserve transformer power", "kind": "grid-data", "type": "numeric", "prompt": "Ideal transformer: input 150 V at 4 A, output 300 V. Calculate output current.", "answer": 2, "unit": "A", "reasonChoices": ["150 × 4 ÷ 300", "300 × 4 ÷ 150", "150 ÷ 300 ÷ 4"], "reason": 0, "why": "For an ideal transformer VpIp = VsIs.", "higher": true}]};
export const experimentOptions={"sources": {"a": [["dc", "DC"], ["ac", "AC"]], "b": [["25", "25 Hz if AC"], ["50", "50 Hz if AC"]], "labels": ["Source type", "AC frequency"], "unit": "complete AC cycles in 1 s"}, "mains": {"a": [["live", "Live"], ["neutral", "Neutral"]], "b": [["earth", "Earth reference"], ["neutral", "Neutral reference"]], "labels": ["First conductor", "Second conductor"], "unit": "V nominal potential difference"}, "power": {"a": [["6", "6 V"], ["12", "12 V"]], "b": [["1", "1 A"], ["2", "2 A"]], "labels": ["Potential difference", "Current"], "unit": "W input power"}, "appliances": {"a": [["60", "60 W"], ["120", "120 W"]], "b": [["10", "10 s"], ["30", "30 s"]], "labels": ["Constant input power", "Duration"], "unit": "J energy transferred"}, "grid": {"a": [["100", "100 V"], ["200", "200 V"]], "b": [["1000", "1000 W"], ["2000", "2000 W"]], "labels": ["Sending potential difference", "Sending power (line R = 1 Ω)"], "unit": "W cable heating loss"}};
export const tasksForEl3=(k,tier='Higher')=>el3Tasks[k].filter(t=>!t.higher||tier==='Higher');
export const validEl3=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];
export const numericEl3=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;
export const advanceEl3=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;
export function experimentResult(k,a,b){let o=experimentOptions[k];if(!o||!o.a.some(x=>x[0]===String(a))||!o.b.some(x=>x[0]===String(b)))throw new RangeError('Choose stated settings.');
let value=k==='sources'?(a==='ac'?+b:0):k==='mains'?(a==='live'?230:0):k==='power'?+a*+b:k==='appliances'?+a*+b:(+b/+a)**2;
return{value,a,b,...(k==='grid'?{I:+b/+a,loss:value,received:+b-value}:{})};}
export const experimentCases=k=>experimentOptions[k].a.flatMap(([a])=>experimentOptions[k].b.map(([b])=>a+':'+b));
export const experimentValid=(k,v)=>experimentCases(k).every(x=>v.observed?.includes(x))&&v.interpretation==='limited';
